-- Generated by python -m scripts.export_analytics_data --bucket YOUR_BUCKET

-- Run statements separately in Athena. STRING staging avoids CSV ISO-date/null parsing errors.

CREATE DATABASE IF NOT EXISTS churn_retention;

CREATE EXTERNAL TABLE IF NOT EXISTS churn_retention.channel_performance_csv (
  `acquisition_channel` STRING,
  `total_customers` STRING,
  `active_customers` STRING,
  `churned_customers` STRING,
  `active_mrr` STRING,
  `revenue_at_risk` STRING,
  `observed_revenue` STRING,
  `average_clv` STRING,
  `average_tenure` STRING,
  `churn_rate` STRING,
  `retention_rate` STRING,
  `arpu` STRING
)
ROW FORMAT SERDE 'org.apache.hadoop.hive.serde2.OpenCSVSerde'
WITH SERDEPROPERTIES ('separatorChar'=',', 'quoteChar'='"', 'escapeChar'='\\')
STORED AS TEXTFILE
LOCATION 's3://customer-churn-retention-analytics/quicksight/channel_performance/'
TBLPROPERTIES ('skip.header.line.count'='1');

CREATE OR REPLACE VIEW churn_retention.channel_performance AS
SELECT CAST(NULLIF("acquisition_channel", '') AS VARCHAR) AS "acquisition_channel",
       CAST(CAST(NULLIF("total_customers", '') AS DOUBLE) AS BIGINT) AS "total_customers",
       CAST(CAST(NULLIF("active_customers", '') AS DOUBLE) AS BIGINT) AS "active_customers",
       CAST(CAST(NULLIF("churned_customers", '') AS DOUBLE) AS BIGINT) AS "churned_customers",
       CAST(NULLIF("active_mrr", '') AS DOUBLE) AS "active_mrr",
       CAST(NULLIF("revenue_at_risk", '') AS DOUBLE) AS "revenue_at_risk",
       CAST(NULLIF("observed_revenue", '') AS DOUBLE) AS "observed_revenue",
       CAST(NULLIF("average_clv", '') AS DOUBLE) AS "average_clv",
       CAST(NULLIF("average_tenure", '') AS DOUBLE) AS "average_tenure",
       CAST(NULLIF("churn_rate", '') AS DOUBLE) AS "churn_rate",
       CAST(NULLIF("retention_rate", '') AS DOUBLE) AS "retention_rate",
       CAST(NULLIF("arpu", '') AS DOUBLE) AS "arpu"
FROM churn_retention.channel_performance_csv;

